const { withAppBuildGradle } = require('@expo/config-plugins');

// Signs release builds with the Kodo release key. android/ is regenerated by
// `expo prebuild --clean`, so the signing config has to be injected here.
// The keystore path and passwords come from ~/.gradle/gradle.properties
// (KODO_UPLOAD_*) locally, or from repository secrets in CI — never from the
// repo. The same key signs every channel (GitHub Releases, IzzyOnDroid, and
// Play later via Play App Signing with this key uploaded as the app signing
// key), so updates install across channels. Losing it means users must
// uninstall to update.
//
// Without the key, debug builds keep the debug key, but any release task
// fails: a public APK signed with the shared debug key could be replaced by
// anyone.
//
// The APK also drops AGP's dependency-info block (an encrypted blob only
// Google can read); IzzyOnDroid and F-Droid reject APKs that carry it.

const SIGNING_CONFIG = `
        release {
            if (project.hasProperty('KODO_UPLOAD_STORE_FILE')) {
                storeFile file(KODO_UPLOAD_STORE_FILE)
                storePassword KODO_UPLOAD_STORE_PASSWORD
                keyAlias KODO_UPLOAD_KEY_ALIAS
                keyPassword KODO_UPLOAD_KEY_PASSWORD
            }
        }`;

const RELEASE_SIGNING = `signingConfig project.hasProperty('KODO_UPLOAD_STORE_FILE') ? signingConfigs.release : signingConfigs.debug`;

const DEPENDENCIES_INFO = `
    dependenciesInfo {
        includeInApk = false
    }`;

const RELEASE_GUARD = `

gradle.taskGraph.whenReady { graph ->
    def releaseTask = graph.allTasks.find { it.project == project && it.name ==~ /(assemble|bundle|package|install)Release/ }
    if (releaseTask && !project.hasProperty('KODO_UPLOAD_STORE_FILE')) {
        throw new GradleException("\${releaseTask.name}: KODO_UPLOAD_STORE_FILE is not set. Release builds must be signed with the Kodo release key; see ARCHITECTURE.md.")
    }
}
`;

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (config) => {
    let gradle = config.modResults.contents;
    if (gradle.includes('KODO_UPLOAD_STORE_FILE')) return config;

    const debugConfig = /(signingConfigs \{\s*debug \{[^}]*\})/;
    const releaseSigning = /(release \{[^{}]*?)signingConfig signingConfigs\.debug/;
    const androidBlock = /^android \{/m;
    if (!debugConfig.test(gradle) || !releaseSigning.test(gradle) || !androidBlock.test(gradle)) {
      throw new Error('with-release-signing: app/build.gradle layout changed; update the plugin.');
    }

    gradle = gradle.replace(debugConfig, `$1${SIGNING_CONFIG}`);
    gradle = gradle.replace(releaseSigning, `$1${RELEASE_SIGNING}`);
    gradle = gradle.replace(androidBlock, `android {${DEPENDENCIES_INFO}`);
    gradle += RELEASE_GUARD;
    config.modResults.contents = gradle;
    return config;
  });
};
